"""Randomised cross-validation of the submission against the reference."""
import json
import random
import subprocess
import sys
import os

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import ref

MAIN = "/workspace/submission/main.py"


def gen_expr(rng, services, depth, budget):
    """Random expression; returns (expr, atoms_used_list)."""
    choices = ["true", "false", "match", "startswith", "endswith", "contains"]
    if depth > 0:
        choices += ["not", "and", "or", "and", "or"]
    kind = rng.choice(choices)
    if kind == "true":
        return {"op": "true"}
    if kind == "false":
        return {"op": "false"}
    if kind in ("match", "startswith", "endswith", "contains"):
        m = rng.randint(0, min(4, len(services)))
        path = [rng.choice(services) for _ in range(m)]
        return {"op": kind, "path": path}
    if kind == "not":
        return {"op": "not", "arg": gen_expr(rng, services, depth - 1, budget)}
    n = rng.randint(0, 3)
    return {"op": kind, "args": [gen_expr(rng, services, depth - 1, budget) for _ in range(n)]}


def gen_bundle(rng):
    nsvc = rng.randint(0, 4)
    services = ["s%d" % i for i in range(nsvc)]
    # sometimes use odd tokens
    if rng.random() < 0.3:
        services = [rng.choice(["a", "A", "β", "ü", "x y", '"q"', "[", "{", ""]) if False else s
                    for s in services]
    rules = []
    nrules = rng.randint(0, 4)
    for _ in range(nrules):
        rules.append({"action": rng.choice(["allow", "drop"]),
                      "when": gen_expr(rng, services, rng.randint(0, 3), None)})
    queries = []
    for _ in range(rng.randint(0, 6)):
        m = rng.randint(0, 6)
        queries.append([rng.choice(services) for _ in range(m)] if services else [])
    return {"services": services, "rules": rules, "queries": queries}


def count_nodes(e):
    if e["op"] in ("true", "false"):
        return 1
    if "path" in e:
        return 1
    if e["op"] == "not":
        return 1 + count_nodes(e["arg"])
    return 1 + sum(count_nodes(a) for a in e["args"])


def run_main(payload_bytes):
    p = subprocess.run([sys.executable, "-I", MAIN], input=payload_bytes,
                       capture_output=True, cwd="/workspace/tmp/dev")
    if p.returncode != 0:
        raise RuntimeError("exit %d: %s" % (p.returncode, p.stderr.decode()[:3000]))
    return [json.loads(l) for l in p.stdout.decode().splitlines()]


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    lines = []
    bundles = []
    for _ in range(count):
        b = gen_bundle(rng)
        # enforce node budget
        while any(count_nodes(r["when"]) > 20 for r in b["rules"]):
            b = gen_bundle(rng)
        bundles.append(b)
        lines.append(json.dumps(b))
    payload = ("\n".join(lines) + "\n").encode()
    out = run_main(payload)
    assert len(out) == len(bundles), (len(out), len(bundles))
    bad = 0
    for b, got in zip(bundles, out):
        want = ref.ref_compile(b)
        if got != want:
            bad += 1
            print("MISMATCH:", json.dumps(b))
            print(" got :", json.dumps(got))
            print(" want:", json.dumps(want))
            if bad > 3:
                return 1
        # semantic acceptance check on random words
        services = b["services"]
        dfa = got["dfa"]
        rows, accs = dfa["next"], dfa["accept"]
        sidx = {s: i for i, s in enumerate(services)}
        for _ in range(40):
            L = rng.randint(0, 14)
            w = [rng.choice(services) for _ in range(L)] if services else []
            s = 0
            for tok in w:
                s = rows[s][sidx[tok]]
            if accs[s] != ref.ref_accept(b["rules"], w):
                print("SEMANTIC MISMATCH", json.dumps(b), w, accs[s],
                      ref.ref_accept(b["rules"], w))
                return 1
        # exhaustive check for tiny alphabets
        if 0 < len(services) <= 2:
            words = [[]]
            for L in range(1, 9):
                words += [[services[i >> k & 1] for k in range(L)] for i in range(1 << L)]
            for w in words:
                s = 0
                for tok in w:
                    s = rows[s][sidx[tok]]
                if accs[s] != ref.ref_accept(b["rules"], w):
                    print("EXHAUSTIVE MISMATCH", json.dumps(b), w)
                    return 1
    print("OK: %d bundles validated" % count)
    return 0


if __name__ == "__main__":
    sys.exit(main())
